const activities = [
  ['Floor Is Lava','🌋',10,'high',['indoor','family','silly','no-equipment','quick'],'Build a safe island path and cross the room without touching the lava.','Choose sturdy floor markers like paper plates or taped shapes. Move from island to island with clear space around you.','The lava rises! Remove one island, rescue a stuffed animal, or cross in slow motion.','#ff9a74'],
  ['Freeze Dance','🪩',8,'medium',['indoor','friends','family','silly','quick'],'Dance your way, then freeze in the wildest pose when the music stops.','Play a favorite song. One person pauses it at random while everyone turns into a statue.','Call out a new style each round: jelly, robot, moon walk, or underwater.','#cbbcf6'],
  ['Cloud Spotting Walk','☁️',20,'low',['outdoor','solo','family','calm','creative'],'Take a gentle walk and turn every cloud into a character or creature.','Walk somewhere safe, look up often, and name the shapes you notice. No need to rush.','Create one big story that connects every cloud you spotted.','#a9dfee'],
  ['Balloon Keep-Up','🎈',10,'medium',['indoor','friends','family','silly','quick'],'Keep a balloon floating using hands, elbows, knees—anything goes.','Clear a safe space, tap the balloon upward, and count how many touches happen before it lands.','No hands round! Try shoulders, feet, or a gentle head bump.','#ffd27e'],
  ['Sidewalk Chalk Quest','🖍️',25,'medium',['outdoor','friends','family','creative'],'Draw a giant path of hops, spins, wiggles, and surprise challenges.','Use chalk to create shapes and directions on a safe sidewalk or driveway, then follow the route.','Let each player add one new square with their own rule.','#ffc0b6'],
  ['Animal Walk Parade','🦀',7,'high',['indoor','anywhere','family','silly','no-equipment','quick'],'Crab-walk, bear-crawl, penguin-waddle, and frog-hop across the room.','Pick an animal and travel to a finish line in its style. Switch animals every trip.','Mix two creatures into one brand-new animal move.','#bce8d1'],
  ['Flashlight Treasure Hunt','🔦',20,'low',['indoor','family','friends','creative'],'Dim the lights and search for hidden treasures by flashlight beam.','A grown-up hides a few safe objects. Search slowly with a flashlight and return each treasure to base.','Add picture clues or make every treasure part of a secret story.','#f5da78'],
  ['Bubble Chase','🫧',10,'high',['outdoor','friends','family','silly','quick'],'Run, reach, duck, and pop as many floating bubbles as you can.','Blow bubbles in an open safe area, then chase without bumping into other players.','Pop only with elbows, toes, or your nose—gently!','#98dce8'],
  ['Sock Basketball','🧦',10,'low',['indoor','solo','family','competitive','quick'],'Roll clean socks into soft balls and aim for a laundry-basket hoop.','Place a basket nearby and take five shots. Step farther back whenever you score.','Assign funny point values or invent a celebration for every basket.','#d4c5f5'],
  ['Color Dash','🌈',8,'high',['indoor','outdoor','friends','family','quick','no-equipment'],'Someone calls a color—race to touch something that matches.','Choose a clear play area. A caller names a color and everyone finds a safe object in that shade.','Call textures, shapes, or starting letters instead of colors.','#ffad93'],
  ['Pillow Island Hop','🏝️',10,'medium',['indoor','solo','family','silly','quick'],'Turn sturdy cushions into islands and explore a brand-new living-room world.','With permission, place firm cushions on a clear floor and step carefully between them.','Each island has a special move: spin, roar, balance, or tiptoe.','#b9e3d0'],
  ['Nature Bingo','🍃',25,'low',['outdoor','solo','family','calm','creative'],'Wander and spot a bird, something tiny, something red, and more.','Make a short list before your walk. Mark each item when you see it—leave nature where it belongs.','Take turns adding one surprising thing to the list.','#cbe89f'],
  ['Mirror Moves','🪞',8,'low',['indoor','friends','family','calm','quick','no-equipment'],'Face a partner and copy every slow, strange, wobbly move they make.','One person leads while the other mirrors. Move slowly enough to stay together, then swap.','Try a giggle-free round or mirror only with your face and hands.','#b8dff1'],
  ['Mission Impossible','🕵️',15,'medium',['indoor','solo','creative','silly','no-equipment'],'Sneak past imaginary lasers, crawl through tunnels, and save the secret file.','Use yarn, pillows, or imagination to mark a safe route through a clear room.','Add a timer, secret password, or stuffed-animal teammate.','#c9b8ed'],
  ['Puddle Jump Lab','💦',15,'high',['outdoor','solo','family','silly'],'Rain boots on. Test tiny jumps, giant splashes, and everything between.','With a grown-up, choose shallow puddles away from traffic and slippery areas.','Rate each jump for splash, sound, and silliness—not style.','#95d9ef'],
  ['Paper Plane Runway','✈️',20,'medium',['indoor','outdoor','friends','family','creative','competitive'],'Fold, launch, chase, adjust, and send your plane flying again.','Make a paper plane and launch it in a clear space. Walk or run to retrieve each flight.','Create landing zones worth different points or award funniest flight.','#f8dd8b'],
  ['Statue Garden','🗿',6,'low',['anywhere','friends','family','calm','quick','no-equipment'],'Become a statue, then change one tiny detail whenever the gardener turns away.','One gardener looks away while statues shift. Freeze before the gardener looks back.','Choose a theme: space museum, jungle garden, or silly breakfast.','#b8e5cf'],
  ['Shadow Tag','👤',15,'high',['outdoor','friends','family','silly','no-equipment'],'Play tag by stepping on shadows instead of tagging people.','On a sunny day in a clear area, choose who is it. Switch roles after a shadow is tagged.','Make giant, tiny, or superhero shapes while you escape.','#d4c7f0'],
  ['Tape-Line Tightrope','🎪',8,'low',['indoor','solo','calm','quick'],'Follow a twisty tape line forward, backward, and sideways without stepping off.','Put painter’s tape on a safe floor in a long curving line. Walk heel-to-toe at your own pace.','Balance a soft toy on your head or add rest-stop circles.','#ffc28f'],
  ['Dance Dice','🎲',10,'medium',['indoor','friends','family','creative','silly','quick'],'Roll a die and let every number unlock a ridiculous dance move.','Assign a move to each number. Roll, perform it for ten seconds, and invite everyone to copy.','Add a second die for speed: slow, normal, or turbo.','#f4aac3'],
  ['Backyard Olympics','🏅',30,'high',['outdoor','friends','family','competitive'],'Invent events where cheering and imagination matter more than winning.','Try a sock toss, funny walk race, longest balance, or noodle javelin in a safe open space.','Give awards for best sound effect, kindest teammate, and biggest laugh.','#f7d879'],
  ['Five-Sense Stroll','👂',15,'low',['outdoor','solo','calm','no-equipment'],'Walk slowly and notice five sights, four sounds, and three textures.','Choose a safe route and pause often. Notice without needing to collect anything.','At the end, name the smallest and biggest thing you noticed.','#addfc5'],
  ['Red Light Remix','🚦',12,'high',['outdoor','indoor','friends','family','competitive','no-equipment'],'Green means go—but purple might mean wiggle and blue might mean crawl.','Pick a caller and a finish line. Agree on each color’s movement before you begin.','Let the winner invent a brand-new color rule for the next round.','#ff9a82'],
  ['Superhero Training','🦸',12,'high',['indoor','outdoor','solo','creative','no-equipment'],'Leap over rivers, balance on rooftops, and practice your heroic landing.','Imagine safe obstacles in an open area. Travel through your training course at your own speed.','Invent a power that changes how you move for one whole round.','#9fd9e6'],
  ['Yoga Story','🐉',15,'low',['indoor','solo','family','calm','creative','no-equipment'],'Stretch through a story with mountains, cats, trees, and sleepy dragons.','Tell a simple adventure and pause for comfortable poses inspired by each character.','Let the next storyteller choose where the adventure goes.','#bde7cd'],
  ['Silly Walk Safari','🦒',10,'medium',['outdoor','indoor','friends','family','silly','quick','no-equipment'],'Cross the room like a giraffe, jellyfish, detective, or tiny dinosaur.','Take turns naming a character. Everyone invents a walk and travels to the finish.','Combine two prompts: sleepy robot or fancy penguin.','#f7c37f'],
  ['Scarf Juggle','🤹',10,'low',['indoor','solo','calm','quick'],'Toss a light scarf, watch it float, and catch it before it lands.','Start with one light scarf in a clear space. Toss gently and try different catches.','Clap once, turn around, or catch on your elbow.','#d0c1f2'],
  ['Follow-the-Leader Trail','🦆',15,'medium',['outdoor','friends','family','creative','no-equipment'],'March, zigzag, tiptoe, and copy every move along the trail.','Choose a leader for one minute. Everyone follows their path and movements, then rotate.','Leaders must include one quiet move and one very silly move.','#f6d776'],
  ['Invisible Ball','🔮',7,'low',['anywhere','friends','family','creative','silly','quick','no-equipment'],'Pass an imaginary ball that can become huge, tiny, sticky, or bouncy.','Show the ball’s size and weight with your movement, then pass it to the next person.','Transform it mid-air into a feather, watermelon, or bubble.','#c8b8f1'],
  ['Sunset Sprint & Stroll','🌅',20,'medium',['outdoor','solo','family','calm','no-equipment'],'Alternate short happy runs with slow noticing walks as the sky changes.','On a safe route, run to a nearby landmark, then walk slowly to the next one.','During every walk break, spot one new color in the sky.','#ffad89'],
  ['Sound-Effect Obstacle Course','💥',15,'high',['indoor','outdoor','friends','family','silly','creative'],'Every hop, crawl, and turn gets its own dramatic sound effect.','Build a simple safe course with clear pathways. Move through while narrating every action.','One player supplies the sound effects for another player’s run.','#9fdde0'],
  ['Cozy Stretch Countdown','🌙',5,'low',['indoor','solo','calm','quick','no-equipment'],'Five gentle movements to help a busy body settle down.','Reach tall, roll shoulders, fold comfortably, hug knees, then take five slow breaths.','Imagine blowing up a balloon with each breath, then let it float away.','#bec0ef']
].map(([name,icon,minutes,effort,tags,blurb,how,remix,color])=>({name,icon,minutes,effort,tags,blurb,how,remix,color}));

const grid=document.querySelector('#activity-grid'),select=document.querySelector('#category-select'),search=document.querySelector('#activity-search'),count=document.querySelector('#result-count'),clearButton=document.querySelector('#clear-filters'),emptyState=document.querySelector('#empty-state'),dialog=document.querySelector('#activity-dialog'),dialogContent=document.querySelector('#dialog-content'),quickFilters=[...document.querySelectorAll('.quick-filter')];
function matches(a){const category=select.value,query=search.value.trim().toLowerCase();const categoryMatch=category==='all'||a.effort===category||a.tags.includes(category)||(category==='quick'&&a.minutes<=10);return categoryMatch&&(!query||`${a.name} ${a.blurb} ${a.effort} ${a.tags.join(' ')}`.toLowerCase().includes(query))}
function card(a,index){const place=a.tags.find(t=>['indoor','outdoor','anywhere'].includes(t))||'anywhere',mood=a.tags.find(t=>['silly','calm','creative','competitive'].includes(t));return `<button class="activity-card" style="--card-color:${a.color}" data-index="${index}" type="button" aria-label="Open ${a.name}"><span class="card-top"><span class="effort-pill">${a.effort} effort</span><span class="card-time">${a.minutes} min</span></span><span class="card-icon" aria-hidden="true">${a.icon}</span><span><h3>${a.name}</h3><p>${a.blurb}</p></span><span class="card-bottom"><span class="card-tags"><span>${place}</span>${mood?`<span>· ${mood}</span>`:''}</span><span class="card-open" aria-hidden="true">↗</span></span></button>`}
function render(){const visible=activities.map((activity,index)=>({activity,index})).filter(({activity})=>matches(activity));grid.innerHTML=visible.map(({activity,index})=>card(activity,index)).join('');count.textContent=`${visible.length} ${visible.length===1?'activity':'activities'} ready to try`;emptyState.hidden=visible.length!==0;grid.hidden=visible.length===0;clearButton.classList.toggle('visible',select.value!=='all'||search.value.trim()!=='');grid.querySelectorAll('.activity-card').forEach(el=>el.addEventListener('click',()=>openActivity(Number(el.dataset.index))))}
function setCategory(value){select.value=value;quickFilters.forEach(button=>button.classList.toggle('active',button.dataset.filter===value));render()}
function clearFilters(){search.value='';setCategory('all')}
function openActivity(index){const a=activities[index];if(!a)return;dialog.style.setProperty('--dialog-color',a.color);dialogContent.innerHTML=`<div class="dialog-inner"><div class="dialog-head"><div><span class="dialog-eyebrow">${a.effort} effort · ${a.minutes} minutes</span><h2>${a.name}</h2></div><span class="dialog-icon" aria-hidden="true">${a.icon}</span></div><p class="dialog-description">${a.blurb}</p><div class="dialog-details"><div class="dialog-panel"><small>How to play</small><p>${a.how}</p></div><div class="dialog-panel"><small>Good to know</small><p>${a.tags.slice(0,4).map(tag=>tag.replace('-',' ')).join(' · ')}</p></div></div><div class="remix"><small>Remix the rules</small><p>${a.remix}</p></div></div>`;if(typeof dialog.showModal==='function')dialog.showModal()}
function surprise(){const pool=activities.map((activity,index)=>({activity,index})).filter(({activity})=>matches(activity));openActivity((pool[Math.floor(Math.random()*pool.length)]||{index:Math.floor(Math.random()*activities.length)}).index)}
select.addEventListener('change',()=>setCategory(select.value));search.addEventListener('input',render);quickFilters.forEach(button=>button.addEventListener('click',()=>setCategory(button.dataset.filter)));clearButton.addEventListener('click',clearFilters);document.querySelector('#empty-clear').addEventListener('click',clearFilters);document.querySelector('#hero-surprise').addEventListener('click',surprise);document.querySelector('#toolbar-surprise').addEventListener('click',surprise);document.querySelector('#dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',event=>{if(event.target===dialog)dialog.close()});render();
